const $=s=>document.querySelector(s);const tint=$('#tint'),desktop=$('#desktop'),opacity=$('#opacity');const presets={amber:{color:'#331f00',opacity:30},blue:{color:'#000d33',opacity:25},gray:{color:'#0d0d0d',opacity:35}};let enabled=true,moving=false;function setOpacity(){document.documentElement.style.setProperty('--opacity',opacity.value/100);$('#opacity-value').value=opacity.value+'%'}function setColor(color){document.documentElement.style.setProperty('--tint',color);$('#custom-color').value=color}function selectPreset(name){let p=presets[name];setColor(p.color);opacity.value=p.opacity;setOpacity();document.querySelectorAll('.preset').forEach(b=>{let active=b.dataset.preset===name;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});$('#status').textContent=name+' tint selected'}document.querySelectorAll('.preset').forEach(b=>b.addEventListener('click',()=>selectPreset(b.dataset.preset)));opacity.addEventListener('input',setOpacity);$('#custom-color').addEventListener('input',e=>{setColor(e.target.value);document.querySelectorAll('.preset').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')})});function setEnabled(value){enabled=value;$('#toggle').setAttribute('aria-checked',enabled);tint.classList.toggle('off',!enabled);if(!enabled)setMoving(false);$('#status').textContent=enabled?'Tint enabled':'Tint disabled'}$('#toggle').addEventListener('click',()=>setEnabled(!enabled));function setMoving(value){moving=value;tint.classList.toggle('moving',moving);$('#move-toggle').firstChild.textContent=moving?'Done moving ':'Move & resize ';$('#move-toggle').setAttribute('aria-pressed',moving);$('#control-hint').textContent=moving?'Drag the top edge to move. Drag the corner to resize. You can also focus either handle and use arrow keys.':'Your mouse works through the tint. Switch to move mode to put it somewhere new.'}$('#move-toggle').addEventListener('click',()=>{if(!enabled)setEnabled(true);setMoving(!moving)});$('#demo-check').addEventListener('click',e=>{const b=e.currentTarget;b.setAttribute('aria-pressed',b.getAttribute('aria-pressed')!=='true')});function applyRect(x,y,w,h){const maxW=desktop.clientWidth,maxH=desktop.clientHeight;w=Math.max(95,Math.min(w,maxW));h=Math.max(65,Math.min(h,maxH-24));x=Math.max(0,Math.min(x,maxW-w));y=Math.max(24,Math.min(y,maxH-h));Object.assign(tint.style,{left:x+'px',top:y+'px',width:w+'px',height:h+'px'})}function bindHandle(id,resize){const handle=$(id);handle.addEventListener('pointerdown',e=>{e.preventDefault();handle.setPointerCapture(e.pointerId);const start={x:e.clientX,y:e.clientY,l:tint.offsetLeft,t:tint.offsetTop,w:tint.offsetWidth,h:tint.offsetHeight};function move(event){const dx=event.clientX-start.x,dy=event.clientY-start.y;applyRect(resize?start.l:start.l+dx,resize?start.t:start.t+dy,resize?start.w+dx:start.w,resize?start.h+dy:start.h)}function end(){handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);handle.removeEventListener('pointercancel',end)}handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',end)});handle.addEventListener('keydown',e=>{const deltas={ArrowLeft:[-10,0],ArrowRight:[10,0],ArrowUp:[0,-10],ArrowDown:[0,10]};if(!deltas[e.key])return;e.preventDefault();const [dx,dy]=deltas[e.key];applyRect(tint.offsetLeft+(resize?0:dx),tint.offsetTop+(resize?0:dy),tint.offsetWidth+(resize?dx:0),tint.offsetHeight+(resize?dy:0))})}bindHandle('#drag-handle',false);bindHandle('#resize-handle',true);$('#reset').addEventListener('click',()=>{tint.removeAttribute('style');setEnabled(true);setMoving(false);selectPreset('amber');$('#demo-check').setAttribute('aria-pressed','false');$('#status').textContent='Demo reset'});new ResizeObserver(()=>{if(tint.style.left)applyRect(tint.offsetLeft,tint.offsetTop,tint.offsetWidth,tint.offsetHeight)}).observe(desktop);const dialog=$('#install-dialog');document.querySelectorAll('.install').forEach(b=>b.addEventListener('click',()=>dialog.showModal()));$('#close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});setOpacity();
